bool tamano_valido(const std::string& texto, int& destino)
{
    if (texto.empty() || texto.size() > 5) {
        return false;
    }
    int candidato = 0;
    for (char c : texto) {
        if (c < '0' || c > '9') {
            return false;
        }
        candidato = candidato * 10 + (c - '0');
    }
    if (candidato < 1 || candidato > 30000) {
        return false;
    }
    destino = candidato;
    return true;
}
